package com.priperi;

import android.app.KeyguardManager;import android.content.*;import android.content.pm.PackageManager;import android.nfc.*;import android.nfc.cardemulation.CardEmulation;import android.nfc.tech.IsoDep;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
import org.json.JSONObject;import java.io.IOException;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Both roles are automatic on this screen. Android reader mode suspends HCE,
 * so jittered foreground slots choose a reader while the other phone emulates. */
final class NfcContactPanel {
 private final ContactCodeActivity activity;final LinearLayout body;private final ImageView symbol;private final TextView status;
 private static final ExecutorService IO=Executors.newFixedThreadPool(2);private final Handler main=new Handler(Looper.getMainLooper());private final AtomicBoolean reading=new AtomicBoolean();
 private volatile IsoDep transport;private NfcAdapter adapter;private CardEmulation cards;private boolean privateReady,busy,canShare;private volatile boolean readerMode;private volatile int generation;private String owner,payload;private Object shareToken;
 private androidx.appcompat.app.AlertDialog confirmation;
 private final Runnable expiry=()->{if(alive()){halt();message("Tap the NFC symbol to try again");}};
 private final Runnable cycle=new Runnable(){public void run(){if(!alive()||busy)return;if(reading.get()){main.postDelayed(this,200);return;}try{if(readerMode){adapter.disableReaderMode(activity);readerMode=false;main.postDelayed(this,1800+ThreadLocalRandom.current().nextInt(900));}else{enableReader();if(canShare)main.postDelayed(this,700+ThreadLocalRandom.current().nextInt(500));}}catch(RuntimeException e){halt();message("Use the QR code to connect");}}};
 private boolean alive(){return privateReady&&!activity.environmentBlocked&&!activity.isFinishing()&&!activity.isDestroyed()&&activity.contactScreenReady()&&owner!=null&&owner.equals(Session.uid());}
 NfcContactPanel(ContactCodeActivity host,LinearLayout parent){activity=host;body=Ui.row(host);body.setGravity(Gravity.CENTER);parent.addView(body,new LinearLayout.LayoutParams(-1,-2));symbol=Ui.symbol(host,"nfc",52,R.color.accent);symbol.setContentDescription("Connect by NFC");symbol.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);symbol.setFocusable(true);symbol.setFilterTouchesWhenObscured(true);symbol.setOnClickListener(v->{if(!alive())return;Ui.tap(symbol);if(adapter!=null&&!enabled()){try{activity.startActivity(new Intent(Settings.ACTION_NFC_SETTINGS));}catch(RuntimeException e){message("Turn NFC on in phone settings");}}else begin();});body.addView(symbol);status=Ui.text(host,"",13,R.color.muted);status.setPadding(Ui.dp(host,14),0,0,0);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(status,new LinearLayout.LayoutParams(0,-2,1));}
 void open(String uid,String name,String code){owner=uid;payload=code;privateReady=true;try{adapter=NfcAdapter.getDefaultAdapter(activity);}catch(RuntimeException e){adapter=null;}if(adapter==null){symbol.setAlpha(.4f);symbol.setEnabled(false);message("Use QR on this phone");return;}symbol.setEnabled(true);symbol.setAlpha(enabled()?1:.5f);if(!enabled()){message("NFC is off · Tap the symbol to enable");return;}begin();}
 private boolean enabled(){try{return adapter!=null&&adapter.isEnabled();}catch(RuntimeException e){return false;}}
 private boolean unlocked(){KeyguardManager k=activity.getSystemService(KeyguardManager.class);return k!=null&&!k.isDeviceLocked();}
 private void begin(){if(!alive()||payload==null||!enabled()||!unlocked())return;halt();int request=generation;canShare=activity.getPackageManager().hasSystemFeature(PackageManager.FEATURE_NFC_HOST_CARD_EMULATION);
  if(canShare)try{cards=CardEmulation.getInstance(adapter);canShare=cards.setPreferredService(activity,new ComponentName(activity,NfcContactService.class));if(canShare)shareToken=NfcContactService.SHARING.open(owner,payload,SystemClock.elapsedRealtime(),value->main.post(()->{if(alive()&&request==generation)received(value);}));}catch(RuntimeException e){canShare=false;}
  message("Hold the backs of both phones together");main.postDelayed(expiry,NfcShareLease.LIFETIME_MS);if(canShare)main.postDelayed(cycle,300+ThreadLocalRandom.current().nextInt(1300));else cycle.run();
 }
 private void enableReader(){readerMode=true;int request=generation;adapter.enableReaderMode(activity,tag->discovered(tag,request),NfcAdapter.FLAG_READER_NFC_A|NfcAdapter.FLAG_READER_SKIP_NDEF_CHECK|NfcAdapter.FLAG_READER_NO_PLATFORM_SOUNDS,null);}
 private void discovered(Tag tag,int request){if(request!=generation||!readerMode||!reading.compareAndSet(false,true))return;String own=payload;IO.execute(()->{IsoDep connection=null;String value=null;
  try{if(request!=generation||!readerMode)throw new IOException();connection=IsoDep.get(tag);if(connection==null)throw new IOException();transport=connection;connection.setTimeout(1500);connection.connect();IsoDep link=connection;value=NfcProtocol.exchange(command->{if(request!=generation||!readerMode)throw new IOException();return link.transceive(command);},own);}catch(IOException|RuntimeException ignored){}finally{if(transport==connection)transport=null;if(connection!=null)try{connection.close();}catch(IOException ignored){}reading.set(false);}String result=value;main.post(()->{if(!alive()||request!=generation)return;if(result!=null)received(result);else message("Keep the phones together, or use QR");});});}
 void received(String value){if(!alive()||busy)return;halt();ContactCode parsed;try{parsed=ContactCode.parse(value);if(parsed.uid.equals(owner))throw new IllegalArgumentException("This is your own contact. Read the other person’s phone instead.");}catch(IllegalArgumentException e){message(e.getMessage());return;}int request=generation;String user=owner;busy=true;message("Finding this account…");Repository.work(activity,v->Repository.resolveCode(v,parsed),peer->{if(!alive()||request!=generation||!user.equals(Session.uid()))return;busy=false;message("Contact received");confirmation=Ui.dialog(activity).setTitle("Chat with @"+peer.optString("username")+"?").setMessage("Only confirm if this code came directly from the person you want to contact. This checks the key, not their real-world identity.").setNegativeButton("Cancel",null).setPositiveButton("Verify and open",(d,w)->{if(!alive()||request!=generation||busy)return;busy=true;Repository.work(activity,v->{if(!user.equals(Session.uid()))throw new SecurityException("Sign in again.");JSONObject current=Repository.resolveCode(v,parsed);v.pin(current);v.contactFlag(parsed.uid,"verified",true);return true;},ok->{if(alive()&&request==generation){activity.startActivity(new Intent(activity,ChatActivity.class).putExtra("peer",parsed.uid));activity.finish();}},error->{if(alive()&&request==generation){busy=false;message(error);}});}).show();},error->{if(alive()&&request==generation){busy=false;message(error);}});}
 private void message(String text){status.setText(text);}
 private void halt(){generation++;busy=false;main.removeCallbacksAndMessages(null);NfcContactService.SHARING.close(shareToken);shareToken=null;if(adapter!=null&&readerMode)try{adapter.disableReaderMode(activity);}catch(RuntimeException ignored){}readerMode=false;if(cards!=null)try{cards.unsetPreferredService(activity);}catch(RuntimeException ignored){}cards=null;IsoDep active=transport;transport=null;if(active!=null)IO.execute(()->{try{active.close();}catch(IOException ignored){}});}
 void hide(){privateReady=false;halt();payload=null;if(confirmation!=null){confirmation.dismiss();confirmation=null;}}
}
